        var me = this,
            readKey = me.readKey,
            name = record.entityName,
            id = record.id,
            seen = me.seen,
            seenKey = name + id,
            result, bucket;

        // Already read it, jump out
        if (seen[seenKey]) {
            return;
        }
        seen[seenKey] = true;

        result = me.result || (me.result = {});
        bucket = result[name]  || (result[name] = {});
        bucket = bucket[readKey] || (bucket[readKey] = []);
        bucket.push(Ext.apply({}, record.modified, record.data));
