            minLength, size, axis;

        me.initConfig(config);

        axis = me.getAxis();

        me.names = me.names[axis];

        me.el = me.getContainerEl().createChild({
            cls: me.cls + ' ' + me.cls + '-' + axis
        });

        if (!me.size) {
            me.cacheStyles();
        }

        minLength = me.getMinLength();
        size = me.size;

