    extend: 'Ext.plugin.Abstract',
    alias: 'plugin.celldragdrop',

                                

    /**
     * @cfg {Boolean} enforceType
     * Set to `true` to only allow drops of the same type.
     *
     * Defaults to `false`.
     */
